import{_ as a,o as s,c as t,a2 as i}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"Deep Workflow Analyzer","description":"","frontmatter":{},"headers":[],"relativePath":"features/analyzer.md","filePath":"features/analyzer.md"}'),l={name:"features/analyzer.md"};function n(r,e,o,p,c,d){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="deep-workflow-analyzer" tabindex="-1">Deep Workflow Analyzer <a class="header-anchor" href="#deep-workflow-analyzer" aria-label="Permalink to &quot;Deep Workflow Analyzer&quot;">​</a></h1><blockquote><p><strong><code>aeroci analyze</code></strong> — Features 1–10</p></blockquote><p>The Analyzer performs static intelligence checks on your workflow YAML files, helping you catch structural problems, inefficiencies, and hidden risks before running the pipeline.</p><hr><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">aeroci</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> analyze</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                             # scan all workflows</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">aeroci</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> analyze</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .github/workflows/ci.yml</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # scan a specific file</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">aeroci</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --analyze</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                     # combine with pre-flight check</span></span></code></pre></div><hr><h2 id="feature-1-—-step-dependency-graph" tabindex="-1">Feature 1 — Step Dependency Graph <a class="header-anchor" href="#feature-1-—-step-dependency-graph" aria-label="Permalink to &quot;Feature 1 — Step Dependency Graph&quot;">​</a></h2><p>Maps <code>needs:</code> relationships between jobs and detects:</p><ul><li>Which jobs run in parallel</li><li>Which jobs block others</li><li>Missing <code>needs:</code> on jobs that require prior outputs</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Output example:</span></span>
<span class="line"><span>  📊 Job Dependency Graph</span></span>
<span class="line"><span>  build  →  test  →  deploy</span></span>
<span class="line"><span>              ↘</span></span>
<span class="line"><span>               lint (parallel)</span></span></code></pre></div><hr><h2 id="feature-2-—-dead-step-detector" tabindex="-1">Feature 2 — Dead Step Detector <a class="header-anchor" href="#feature-2-—-dead-step-detector" aria-label="Permalink to &quot;Feature 2 — Dead Step Detector&quot;">​</a></h2><p>Identifies steps that can <strong>never execute</strong> because they have an <code>if:</code> condition that always evaluates to <code>false</code>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">- </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Deploy to Prod</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # ← flagged as dead step</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  run</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">./deploy.sh</span></span></code></pre></div><hr><h2 id="feature-3-—-duplicate-step-detector" tabindex="-1">Feature 3 — Duplicate Step Detector <a class="header-anchor" href="#feature-3-—-duplicate-step-detector" aria-label="Permalink to &quot;Feature 3 — Duplicate Step Detector&quot;">​</a></h2><p>Finds identical <code>run:</code> scripts repeated across multiple steps or jobs. Suggests extracting them into a reusable composite action.</p><hr><h2 id="feature-4-—-step-duration-estimator" tabindex="-1">Feature 4 — Step Duration Estimator <a class="header-anchor" href="#feature-4-—-step-duration-estimator" aria-label="Permalink to &quot;Feature 4 — Step Duration Estimator&quot;">​</a></h2><p>Provides intelligent time estimates for each step based on keywords:</p><table tabindex="0"><thead><tr><th>Pattern</th><th>Estimated Duration</th></tr></thead><tbody><tr><td><code>npm install</code> / <code>pip install</code></td><td>~60s</td></tr><tr><td><code>npm test</code> / <code>pytest</code></td><td>~30s</td></tr><tr><td><code>npm run build</code></td><td>~45s</td></tr><tr><td><code>docker build</code></td><td>~120s</td></tr><tr><td><code>actions/checkout</code></td><td>~5s</td></tr></tbody></table><p>These estimates are used by the Profiler&#39;s cost calculator.</p><hr><h2 id="feature-5-—-shell-compatibility-checker" tabindex="-1">Feature 5 — Shell Compatibility Checker <a class="header-anchor" href="#feature-5-—-shell-compatibility-checker" aria-label="Permalink to &quot;Feature 5 — Shell Compatibility Checker&quot;">​</a></h2><p>Detects <code>bash</code>-specific syntax used in steps that run with <code>sh</code> (the default):</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">- </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">run</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    arr=(a b c)     # ← bash array syntax, fails in sh</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    echo \\\${arr[0]}</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  shell</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # ← incompatible</span></span></code></pre></div><p><strong>Flagged patterns:</strong></p><ul><li>Arrays: <code>arr=(...)</code></li><li><code>[[ ]]</code> double brackets</li><li>Process substitution: <code>&lt;(...)</code></li><li>Here-strings: <code>&lt;&lt;&lt; &quot;...&quot;</code></li></ul><hr><h2 id="feature-6-—-secret-flow-map" tabindex="-1">Feature 6 — Secret Flow Map <a class="header-anchor" href="#feature-6-—-secret-flow-map" aria-label="Permalink to &quot;Feature 6 — Secret Flow Map&quot;">​</a></h2><p>Traces the path of each <code>secrets.*</code> reference through:</p><ul><li>Workflow-level <code>env:</code> blocks</li><li>Job-level <code>env:</code> blocks</li><li>Step <code>env:</code> blocks</li><li><code>run:</code> script inline references</li></ul><p>Flags secrets that flow into unsafe contexts (e.g., directly into <code>run:</code> scripts).</p><hr><h2 id="feature-7-—-artifact-lifecycle-tracker" tabindex="-1">Feature 7 — Artifact Lifecycle Tracker <a class="header-anchor" href="#feature-7-—-artifact-lifecycle-tracker" aria-label="Permalink to &quot;Feature 7 — Artifact Lifecycle Tracker&quot;">​</a></h2><p>Verifies that every <code>actions/upload-artifact</code> has a corresponding <code>actions/download-artifact</code> in a dependent job, and vice versa.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>⚠ [AeroCI Warning] Artifact &quot;build-output&quot; uploaded in job:build</span></span>
<span class="line"><span>  but never downloaded in any dependent job</span></span></code></pre></div><hr><h2 id="feature-8-—-circular-job-dependency-detector" tabindex="-1">Feature 8 — Circular Job Dependency Detector <a class="header-anchor" href="#feature-8-—-circular-job-dependency-detector" aria-label="Permalink to &quot;Feature 8 — Circular Job Dependency Detector&quot;">​</a></h2><p>GitHub Actions will fail at queue time if <code>needs:</code> creates a cycle. AeroCI detects it locally:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">jobs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  a</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    needs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">b</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # ← CYCLE!</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  b</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    needs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">a</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>⚠ Circular dependency detected: a → b → a</span></span></code></pre></div><hr><h2 id="feature-9-—-concurrency-group-conflict-analyzer" tabindex="-1">Feature 9 — Concurrency Group Conflict Analyzer <a class="header-anchor" href="#feature-9-—-concurrency-group-conflict-analyzer" aria-label="Permalink to &quot;Feature 9 — Concurrency Group Conflict Analyzer&quot;">​</a></h2><p>Detects when multiple jobs use the same <code>concurrency.group</code> string, which could cause unexpected cancellations.</p><hr><h2 id="feature-10-—-workflow-complexity-score" tabindex="-1">Feature 10 — Workflow Complexity Score <a class="header-anchor" href="#feature-10-—-workflow-complexity-score" aria-label="Permalink to &quot;Feature 10 — Workflow Complexity Score&quot;">​</a></h2><p>Produces a single <strong>0–100 score</strong> rating the complexity of your workflow:</p><table tabindex="0"><thead><tr><th>Score</th><th>Label</th></tr></thead><tbody><tr><td>0–25</td><td>🟢 Simple</td></tr><tr><td>26–50</td><td>🟡 Moderate</td></tr><tr><td>51–75</td><td>🟠 Complex</td></tr><tr><td>76–100</td><td>🔴 Very Complex</td></tr></tbody></table><p><strong>Factors considered:</strong></p><ul><li>Number of jobs</li><li>Total step count</li><li>Matrix dimensions</li><li>Number of <code>needs:</code> edges</li><li>Use of dynamic expressions</li></ul><p>A high complexity score is a signal to split your workflow into multiple files.</p>`,53)])])}const k=a(l,[["render",n]]);export{u as __pageData,k as default};
